// 算法1：直接计算 时间复杂度 O(n²)
// a[n]*x^n + a[n-1]*x^(n-1) + ... + a[1]*x + a[0]
double poly1(int n, double a[], double x) {
    double sum = 0.0;
    for (int i = 0; i <= n; i++) {
        double term = a[i];
        for (int j = 0; j < i; j++) term *= x;
        sum += term;
    }
    return sum;
}

// 算法2：秦九韶算法 时间复杂度 O(n)
// a[n]*x^n + a[n-1]*x^(n-1) + ... + a[0]
// = (...((a[n]*x) + a[n-1])*x + ... )*x + a[0]
double poly2(int n, double a[], double x) {
    double sum = a[n];
    for (int i = n-1; i >= 0; i--)
        sum = sum * x + a[i];
    return sum;
}

// 结论：算法2比算法1快得多！
// 当 n=10000 时，算法1执行约 5000 万次运算
// 算法2仅执行 10000 次运算

// 当 x=2, n=3, a=[1,2,3,4] 时：
// poly1: 1 + 2*2 + 3*4 + 4*8 = 1+4+12+32 = 49
// poly2: (((4*2)+3)*2+2)*2+1 = (11*2+2)*2+1 = 24*2+1 = 49

// 1. O(1) - 常数阶
int getFirst(int arr[]) { return arr[0]; }

// 2. O(log n) - 对数阶（二分查找）
int binarySearch(int arr[], int n, int target) {
    int left = 0, right = n-1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (arr[mid] == target) return mid;
        else if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

// 3. O(n) - 线性阶
int findMax(int arr[], int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++)
        if (arr[i] > max) max = arr[i];
    return max;
}

// 4. O(n log n) - 线性对数阶（归并排序）
void mergeSort(int arr[], int l, int r) {
    if (l < r) {
        int m = (l + r) / 2;
        mergeSort(arr, l, m);      // T(n/2)
        mergeSort(arr, m+1, r);    // T(n/2)
        merge(arr, l, m, r);       // O(n)
    }   // 总时间 T(n) = 2*T(n/2) + O(n) = O(n log n)
}

// 5. O(n²) - 平方阶（冒泡排序）
void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n-1; i++)
        for (int j = 0; j < n-i-1; j++)
            if (arr[j] > arr[j+1])
                swap(arr[j], arr[j+1]);
}

// 6. O(2ⁿ) - 指数阶（斐波那契的朴素递归）
int fib(int n) {
    if (n <= 1) return n;
    return fib(n-1) + fib(n-2);  // 重复计算！
}
// 改进：动态规划 O(n)
int fib_dp(int n) {
    int f[n+1]; f[0]=0; f[1]=1;
    for (int i=2; i<=n; i++) f[i] = f[i-1] + f[i-2];
    return f[n];
}
